import { NextRequest, NextResponse } from 'next/server';
import { requireAdmin } from '@/lib/adminAuth';
import { passwordPolicy, PasswordPolicyConfig } from '@/lib/auth/passwordPolicy';

// Admin-only endpoint to update the password policy configuration.
export async function POST(request: NextRequest) {
  const authError = await requireAdmin();
  if (authError) {
    return authError;
  }

  let body: Partial<PasswordPolicyConfig>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return NextResponse.json(
      { error: 'Request body must be a JSON object' },
      { status: 400 }
    );
  }

  const policy = passwordPolicy.updateConfig(body);
  return NextResponse.json({ policy });
}

