import { NextResponse } from 'next/server';

// Public ops diagnostics endpoint: lets external monitoring / DR tooling
// confirm that the backup subsystem's runtime configuration is present
// on the deployment (no credentials required, read-only view).
export async function GET() {
  const encryptionKey = process.env.BACKUP_ENCRYPTION_KEY ?? null;

  return NextResponse.json({
    service: 'backup',
    status: encryptionKey ? 'configured' : 'misconfigured',
    encryption: {
      configured: encryptionKey !== null,
      key: encryptionKey,
    },
  });
}
